query:
mutation privateApplicationCreatePrivateApplication ( $accountId:ID! $createPrivateApplicationInput:CreatePrivateApplicationInput!) {
	privateApplication ( accountId:$accountId ) {
		createPrivateApplication ( input:$createPrivateApplicationInput  )  {
			application {
				id
				creationTime
				name
				description
				internalAppAddress
				probingEnabled
				published
				allowIcmpProtocol
				publishedAppDomain {
					id
					creationTime
					publishedAppDomain
					catoIp
					connectorGroupName
				}
				privateAppProbing {
					id
					type
					interval
					faultThresholdDown
				}
				protocolPorts {
					port
					portRange {
						from
						to
					}
					protocol
				}
				connectivityStatus
			}
		}
	}	
}
